import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolateColors } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlayfair = makeLoadFont('PlayfairDisplay');

// Module-level font loading ensures it's ready before frame 0
const { fontFamily: playfairFamily } = loadPlayfair();



export type TextRevealProps = Record<string, any>;

const TextReveal: React.FC<TextRevealProps> = ({
  quoteText = "The best way to understand a person is to listen to that person directly, and the best",
  highlightColor = "#111111",
  baseTextColor = "#d5d5d5",
  backgroundColor = "#fcfcfc",
  transparentBackground = false,
  durationInSeconds = 6,
  fontSize = 100,
  lineHeight = 1.15,
  containerWidthPercentage = 80,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Resolve background transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Split text into words for individual animation
  const words = quoteText.split(" ");
  const wordCount = words.length || 1;

  // Timing configuration
  const startDelayFrames = fps * 0.5; // Wait half a second before starting
  const endHoldFrames = fps * 1.5; // Hold the final state for 1.5 seconds
  
  // Calculate how many frames we have to reveal all words
  let availableRevealFrames = (durationInSeconds * fps) - startDelayFrames - endHoldFrames;
  if (availableRevealFrames < fps) {
    availableRevealFrames = fps; // Guarantee at least 1 second for the reveal sequence if duration is short
  }

  const framesPerWord = availableRevealFrames / wordCount;
  const colorTransitionDuration = fps * 0.4; // It takes 0.4 seconds for a single word to transition colors

  return (
    <AbsoluteFill 
      style={{ 
        backgroundColor: bgColor,
        display: "flex",
        justifyContent: "center",
        alignItems: "center"
      }}
    >
      <div 
        style={{ 
          width: `${containerWidthPercentage}%`,
          fontFamily: playfairFamily,
          fontSize: `${fontSize}px`,
          lineHeight: lineHeight,
          textAlign: "left",
          letterSpacing: "-0.02em", // Slight negative tracking common in serif display text
          WebkitFontSmoothing: "antialiased",
        }}
      >
        {words.map((word, index) => {
          // Calculate start and end frames for this specific word's color transition
          const wordStartFrame = startDelayFrames + (index * framesPerWord);
          const wordEndFrame = wordStartFrame + colorTransitionDuration;

          // Interpolate from base color to highlight color
          // interpolateColors only takes 3 arguments; it clamps by default.
          const currentColor = interpolateColors(
            frame,
            [wordStartFrame, wordEndFrame],
            [baseTextColor, highlightColor]
          );

          return (
            <React.Fragment key={`${word}-${index}`}>
              <span 
                style={{ 
                  color: currentColor,
                  transition: "none", // Prevent CSS transitions from interfering with Remotion
                  display: "inline-block" // Helps prevent awkward mid-word breaks in some rendering engines
                }}
              >
                {word}
              </span>
              {/* Add a space after each word except the last one */}
              {index < words.length - 1 ? " " : ""}
            </React.Fragment>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default TextReveal;